CREATE TABLE IF NOT EXISTS work_log_auto_draft_jobs(subject_id TEXT NOT NULL,capture_id TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,log_id TEXT,item_id TEXT,last_error TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,completed_at INTEGER,PRIMARY KEY(subject_id,capture_id));
CREATE INDEX IF NOT EXISTS idx_wl_auto_jobs_state ON work_log_auto_draft_jobs(state,updated_at);
CREATE TABLE IF NOT EXISTS work_log_auto_metadata(subject_id TEXT NOT NULL,log_id TEXT NOT NULL,origin TEXT NOT NULL DEFAULT 'CAPTURE_AUTO_V1',grouping_key TEXT NOT NULL,sequence INTEGER NOT NULL DEFAULT 1,user_edited_summary INTEGER NOT NULL DEFAULT 0,generated_summary TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(subject_id,log_id),UNIQUE(subject_id,grouping_key,sequence));
CREATE TABLE IF NOT EXISTS work_log_auto_item_metadata(subject_id TEXT NOT NULL,item_id TEXT NOT NULL,grouping_key TEXT NOT NULL,first_capture_at TEXT NOT NULL,last_capture_at TEXT NOT NULL,generated_fields_json TEXT NOT NULL DEFAULT '{}',user_edited_fields_json TEXT NOT NULL DEFAULT '[]',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(subject_id,item_id));
